customCSS:
.t, .history { color: #9893a5; }
.join { color: #618774; }
.part, .quit { color: #9893a5; }
.kick, .error { color: #b4637a; }
.notice { color: #ea9d34; }
.action { color: #907aa9; }
.mode, .nick, .topic, .server { color: #56949f; }
.highlight { color: #575279; background-color: #d0d8d8; border-left: 3px solid #907aa9; padding-left: 8px; }
.reply { color: #9893a5; border-left: 2px solid #286983; padding-left: 6px; }
.oper { color: #faf4ed; background-color: #ea9d34; }
.reactions { color: #286983; background-color: #f2e9e1; }
.card { background-color: #f2e9e1; border-color: #9893a5; }
.card-title { color: #286983; }
.card-desc { color: #9893a5; }
.daychange { color: #9893a5; border-color: #f2e9e1; }
